from hran_elementmanager2g.utils.loggers import logger

try:
    from robot.utils.platform import UNIXY, IRONPYTHON
    from robot.errors import TimeoutError

    if UNIXY:
        from robot.running.timeouts.posix import Timeout

        class Timeout(Timeout):

            def __init__(self, timeout, error=TimeoutError('Keyword timeout exceeded')):
                super(Timeout, self).__init__(timeout, error)

    elif IRONPYTHON:
        from robot.running.timeouts.ironpython import Timeout

        class Timeout(Timeout):

            def __init__(self, timeout, error=TimeoutError('Keyword timeout exceeded')):
                super(Timeout, self).__init__(timeout, error)

    else:
        from robot.running.timeouts.windows import Timeout

        class Timeout(Timeout):

            def __init__(self, timeout, error=TimeoutError('Keyword timeout exceeded')):
                super(Timeout, self).__init__(timeout, error)

    def run_kw_with_timeout(runnable, timeout, timeout_msg, args=None, kwargs=None):
        executable = lambda: runnable(*(args or ()), **(kwargs or {}))
        return Timeout(timeout, TimeoutError(timeout_msg)).execute(executable)

except ImportError:
    def run_kw_with_timeout(runnable, timeout, timeout_msg, args=None, kwargs=None):
        logger.warning('cannot import robot timeouts')
        executable = lambda: runnable(*(args or ()), **(kwargs or {}))
        return executable()
